/* AppTodoMapper.update */
/* 승인처리 */
UPDATE CSPD001TM SET
	AI_INPT_APPV_STCD = '110', /* 코드그룹 - 140 */
	LST_DB_CHG_ID = #{lstDbChgId},
	LST_DB_CHG_DTM = TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS'),
	TRN_LOG_SRNO = #{trnLogSrno}
WHERE INPT_MST_SRNO = #{inptMstSrno}

mapper.select:
/* AppTodoMapper.selectMemoList */
SELECT A.AI_INPT_APPV_OPI_SRNO , A.AI_INPT_APPV_OPI_USG_YN , A.AI_INPT_APPV_OPI_TXT , A.AI_INPT_APPV_OPI_RGS_DTM , A.AI_INPT_APPV_OPI_END_DTM , A.TRN_LOG_SRNO , A.LST_DB_CHG_ID , A.LST_DB_CHG_DTM FROM CSPD110TI A
ORDER BY A.LST_DB_CHG_DTM DESC



SELECT AI_INPT_APPV_SRNO 			
	 , AI_INPT_TPY_SAVE_YN
	 , AI_INPT_CRPE_ENO
	 , AI_INPT_QLAS_PRC_STS_CD
FROM CSPD005TH 
WHERE INPT_MST_SRNO = #{inptMstSrno} 
AND AI_INPT_APPV_SRNO = (
	SELECT MAX(AI_INPT_APPV_SRNO) 
	FROM CSPD005TH WHERE INPT_MST_SRNO = #{inptMstSrno}
)

/* AppTodoMapper.selectMemoListTotCnt */
SELECT COUNT(*) totcnt
  FROM CSPD110TI A
